jsLib:
var DM5_BASE='https://www.dm5.com';
function dm5Doc(html,url){return org.jsoup.Jsoup.parse(String(html),url||DM5_BASE);}
function dm5Abs(url){url=String(url||'');if(/^https?:\/\//i.test(url))return url;if(url.indexOf('//')===0)return 'https:'+url;return DM5_BASE+(url.charAt(0)==='/'?'':'/')+url;}
function dm5Bg(e){if(!e)return '';var img=e.selectFirst('img');if(img&&img.hasAttr('src'))return dm5Abs(img.attr('src'));var p=e.selectFirst('p.mh-cover');if(!p)return '';var m=/url\([\s"']*([^\)"']+)/.exec(p.attr('style'));return m?dm5Abs(m[1]):'';}
function dm5Entries(doc,search){var nodes=doc.select(search?'ul.mh-list > li, div.banner_detail_form':'ul.mh-list > li > div.mh-item');var list=[];for(var i=0;i<nodes.size();i++){var e=nodes.get(i);var a=e.selectFirst(search?'.title > a':'h2.title > a');if(!a)continue;list.push({name:a.text(),url:dm5Abs(a.attr('href')),cover:dm5Bg(e),author:'',kind:'',intro:'',latest:''});}return list;}
function dm5ListToLegado(data, legadoJava){legadoJava.setContent(JSON.stringify(data));return legadoJava.getElements('@json:$[*]');}
function dm5Var(script,name){var m=new RegExp('\\bvar\\s+'+name+'\\s*=\\s*([\\s\\S]*?);').exec(script);return m?m[1].replace(/^\s*["']|["']\s*$/g,'').trim():'';}
function dm5Radix(s,radix){var n=0;for(var i=0;i<s.length;i++){var c=s.charCodeAt(i),v=c>=48&&c<=57?c-48:c>=97&&c<=122?c-87:c-29;n=n*radix+v;}return n;}
// One-pass token replacement like Keiyoushi's Unpacker; handles common Dean Edwards Packer layout.
function dm5Unpack(js){var s=String(js);if(/var\s+pix\s*=/.test(s))return s;
var re=/\}\s*\(\s*(['"])((?:\\.|(?!\1)[\s\S])*?)\1\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(['"])((?:\\.|(?!\5)[\s\S])*?)\5\.split\(\s*['"]\|['"]\s*\)/;
var m=re.exec(s);if(!m)throw Error('DM5 Packer arguments not found');
var payload=m[2].replace(/\\'/g,"'").replace(/\\"/g,'"');var radix=Number(m[3]),words=m[6].split('|');
return payload.replace(/\w+/g,function(k){var i=dm5Radix(k,radix);return i<words.length&&words[i]?words[i]:k;});}
function dm5GetPage(legadoJava,url,referer){return String(legadoJava.ajax(url+',{"headers":{"Referer":'+JSON.stringify(referer)+'}}'));}
function dm5ImageFromScript(js){var code=dm5Unpack(js);var pix=/var\s+pix\s*=\s*["']([^"']+)/.exec(code);var pv=/var\s+pvalue\s*=\s*\[\s*["']([^"']+)/.exec(code);var suffix=/pix\s*\+\s*pvalue\s*\[\s*i\s*\]\s*\+\s*["']([^"']*)/.exec(code);if(!pix||!pv||!suffix)throw Error('DM5 unpacked image URL incomplete');return pix[1]+pv[1]+suffix[1];}
